class Solution:
    def maxWeight(self, weights: List[int], w1: int, w2: int) -> int:
        dp = [[0] * (w2 + 1) for _ in range(w1 + 1)]
        for x in weights:
            for a in range(w1, -1, -1):
                for b in range(w2, -1, -1):
                    best = dp[a][b]
                    if a >= x: best = max(best, dp[a - x][b] + x)
                    if b >= x: best = max(best, dp[a][b - x] + x)
                    dp[a][b] = best
        return dp[w1][w2]

