from functools import lru_cache
class Solution:
    def maxWeight(self, weights: List[int], w1: int, w2: int) -> int:
        @lru_cache(maxsize=None)
        def f(i, a, b):
            if i == len(weights): return 0
            x = weights[i]
            best = f(i + 1, a, b)
            if a >= x: best = max(best, x + f(i + 1, a - x, b))
            if b >= x: best = max(best, x + f(i + 1, a, b - x))
            return best
        return f(0, w1, w2)

