class Solution {
    vector<vector<vector<int>>> memo;
    vector<int>* w;
    int f(int i, int a, int b) {
        if (i == w->size()) return 0;
        int &m = memo[i][a][b];
        if (m != -1) return m;
        int x = (*w)[i];
        m = f(i + 1, a, b);
        if (a >= x) m = max(m, x + f(i + 1, a - x, b));
        if (b >= x) m = max(m, x + f(i + 1, a, b - x));
        return m;
    }
public:
    int maxWeight(vector<int>& weights, int w1, int w2) {
        w = &weights;
        memo.assign(weights.size() + 1, vector<vector<int>>(w1 + 1, vector<int>(w2 + 1, -1)));
        return f(0, w1, w2);
    }
};

