class Solution {
    private int[] ws;
    private Integer[][][] memo;
    private int f(int i, int a, int b) {
        if (i == ws.length) return 0;
        if (memo[i][a][b] != null) return memo[i][a][b];
        int x = ws[i], best = f(i + 1, a, b);
        if (a >= x) best = Math.max(best, x + f(i + 1, a - x, b));
        if (b >= x) best = Math.max(best, x + f(i + 1, a, b - x));
        return memo[i][a][b] = best;
    }
    public int maxWeight(int[] weights, int w1, int w2) {
        ws = weights;
        memo = new Integer[weights.length + 1][w1 + 1][w2 + 1];
        return f(0, w1, w2);
    }
}

